INSERT INTO OM_ORDER_LINES_TBL (HEADER_ID, ITEM_ID, QUANTITY, COST_PER_ITEM, IS_PAID, IS_SERVED)
SELECT (SELECT MAX(HEADER_ID) FROM OM_ORDER_HEADERS_TBL), ITEM_ID, 2, 40.00, 1, 1
  FROM FOO_FOOD_MST WHERE ITEM_CODE = 'B02';

