SELECT 'Cashier2', 0, 1, 1, CUSTOMER_ID, 'Table 4', 'PENDING'
  FROM CUST_PERSON_ACC WHERE CUSTOMER_NUMBER = 'CUST001';

INSERT INTO OM_ORDER_LINES_TBL (HEADER_ID, ITEM_ID, QUANTITY, COST_PER_ITEM, IS_PAID, IS_SERVED)
